CREATE TABLE public.admin_creation_authority(user_id uuid PRIMARY KEY,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_creation_authority TO authenticated; GRANT ALL ON public.admin_creation_authority TO service_role;
ALTER TABLE public.admin_creation_authority ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Own creation authority" ON public.admin_creation_authority FOR SELECT TO authenticated USING(user_id=auth.uid());
INSERT INTO public.admin_creation_authority(user_id) SELECT DISTINCT user_id FROM public.user_roles WHERE role='admin';
CREATE FUNCTION public.can_create_admin(_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.has_role(_user,'admin') AND EXISTS(SELECT 1 FROM public.admin_creation_authority WHERE user_id=_user) $$;
CREATE FUNCTION public.guard_admin_role_changes() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF ((TG_OP<>'DELETE' AND NEW.role='admin') OR (TG_OP<>'INSERT' AND OLD.role='admin')) AND COALESCE(auth.role(),'')<>'service_role' AND NOT public.can_create_admin(auth.uid()) THEN RAISE EXCEPTION 'Admin creation authority required'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER protect_admin_roles BEFORE INSERT OR UPDATE OR DELETE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.guard_admin_role_changes();
CREATE TABLE public.portal_exams(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),department text NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',questions jsonb NOT NULL DEFAULT '[]',published boolean NOT NULL DEFAULT false,opens_at timestamptz,closes_at timestamptz,duration_minutes integer NOT NULL DEFAULT 60 CHECK(duration_minutes BETWEEN 1 AND 240),created_by uuid NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.portal_exams TO authenticated; GRANT ALL ON public.portal_exams TO service_role;
ALTER TABLE public.portal_exams ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.eligible_for_portal_exam(_user uuid,_dept text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT NOT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user AND role IN ('admin','sub_admin','department_head')) AND EXISTS(SELECT 1 FROM public.applications a LEFT JOIN public.department_placements p ON p.application_id=a.id WHERE a.user_id=_user AND COALESCE(p.current_department,a.first_department)=_dept AND a.status NOT IN ('waiting_list','rejected')) $$;
CREATE POLICY "Heads read department exams" ON public.portal_exams FOR SELECT TO authenticated USING(department=public.head_department(auth.uid()));
CREATE POLICY "Students read published eligible exams" ON public.portal_exams FOR SELECT TO authenticated USING(published AND public.eligible_for_portal_exam(auth.uid(),department));
CREATE TABLE public.portal_exam_attempts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),exam_id uuid NOT NULL REFERENCES public.portal_exams(id),user_id uuid NOT NULL,department text NOT NULL,questions jsonb NOT NULL,answers jsonb NOT NULL DEFAULT '{}',started_at timestamptz NOT NULL DEFAULT now(),deadline timestamptz NOT NULL,submitted_at timestamptz,UNIQUE(exam_id,user_id));
GRANT SELECT ON public.portal_exam_attempts TO authenticated; GRANT ALL ON public.portal_exam_attempts TO service_role;
ALTER TABLE public.portal_exam_attempts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read own or department attempts" ON public.portal_exam_attempts FOR SELECT TO authenticated USING(user_id=auth.uid() OR department=public.head_department(auth.uid()));
CREATE TABLE public.portal_exam_grades(attempt_id uuid PRIMARY KEY REFERENCES public.portal_exam_attempts(id),department text NOT NULL,points jsonb NOT NULL DEFAULT '{}',feedback text NOT NULL DEFAULT '',total numeric NOT NULL DEFAULT 0,maximum numeric NOT NULL DEFAULT 0,published boolean NOT NULL DEFAULT false,graded_by uuid NOT NULL,graded_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.portal_exam_grades TO authenticated; GRANT ALL ON public.portal_exam_grades TO service_role;
ALTER TABLE public.portal_exam_grades ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Heads read own grades" ON public.portal_exam_grades FOR SELECT TO authenticated USING(department=public.head_department(auth.uid()));
CREATE POLICY "Students read published grades" ON public.portal_exam_grades FOR SELECT TO authenticated USING(published AND EXISTS(SELECT 1 FROM public.portal_exam_attempts a WHERE a.id=attempt_id AND a.user_id=auth.uid()));